const IND={I1:'Promoción y participación',I2:'Planificación anticipada',I3:'Plan nacional',I4:'Integración en atención primaria',I5:'Autoridad nacional',I6:'Congresos',I7:'Publicaciones',I8:'Consumo de opioides',I9:'Disponibilidad de medicamentos',I10:'Morfina oral',I11:'Educación médica',I12:'Especialización',I13:'Servicios especializados para adultos',I14:'Servicios pediátricos'};
const DIM={I13:'Servicios para adultos · I13',Gobernanza:'Gobernanza',Acceso:'Acceso a medicamentos',Capacidad_Operativa:'Capacidad operativa',...Object.fromEntries(Object.entries(IND).filter(([k])=>k!=='I13').map(([k,v])=>[k,k+' · '+v]))};
const Q={EI1:'Vía acceso (C1)',EI2:'Vía capacidad (C1)',EI3:'Vía investigación (C2)',total_indirect:'Suma de productos indirectos',total_effect:'Asociación total especificada',EI1_minus_EI2:'Diferencia entre vías',indirect_fraction:'Cociente indirecto / total',proportion_mediated:'Cociente indirecto / total'};
const METHODS={
 '00_datos':['Preparación de los datos','Documenta la cohorte, las exclusiones y la procedencia de los indicadores. Los faltantes son ausencia de información; no equivalen al nivel mínimo.'],
 '01_potencia':['Potencia y precisión','Examina la capacidad del diseño para detectar asociaciones bajo supuestos concretos. Una potencia limitada aconseja leer la amplitud de los intervalos, no concluir ausencia de relación.'],
 '02_descriptivos':['Descriptivos y faltantes','Resume distribución, dispersión y datos ausentes. Los resúmenes archivados pueden utilizar una imputación; el mapa utiliza únicamente datos observados.'],
 '03_psicometria':['Fiabilidad de los componentes','Alfa, omega y colinealidad describen propiedades de la medición. La consistencia interna no establece validez ni convierte un componente formativo en factor reflectivo.'],
 '04_validez_discriminante':['Validez discriminante','Examina cuánto se distinguen los componentes; una separación limitada puede dificultar atribuir asociaciones a una dimensión concreta.'],
 '04a_ave':['Varianza extraída · AVE','Diagnóstico de cuánto recogen los factores de sus indicadores. Su interpretación formal requiere un modelo reflectivo defendible.'],
 '04b_htmt':['Distinción entre dimensiones · HTMT','Compara asociaciones entre y dentro de componentes. En acceso y capacidad es un diagnóstico auxiliar, no una prueba definitiva de validez.'],
 '04c_bifactor':['Modelo bifactor','Compara una dimensión general con componentes específicos; ajuste y estabilidad son distintos de utilidad sustantiva.'],
 '04d_esem':['ESEM','Explora cargas cruzadas entre dimensiones. Las cargas dependen de rotación, muestra y supuestos de medición.'],
 '04e_omega_h':['Omega jerárquico','Describe cuánto de la variación puede atribuirse a una dimensión general bajo el modelo factorial.'],
 '04f_efa':['Estructura factorial exploratoria','Examina el número y la organización de factores; la estructura exploratoria no demuestra una secuencia causal.'],
 '04g_unifactorial':['Uno frente a varios factores','Contrasta formas de representar la covariación. Una mejora de ajuste no valida por sí sola una interpretación sustantiva.'],
 '05_cmb':['Sesgo de método común','Busca señales compatibles con una fuente compartida de medición. La prueba de Harman no descarta sesgo de método común.'],
 '06_invarianza':['Comparabilidad de la medición','Examina si los componentes conservan propiedades entre grupos. Los diagnósticos no garantizan equivalencia de escala.'],
 '07_correlaciones':['Correlaciones y ajustes','Describe asociaciones bivariadas y condicionadas a covariables. Cambiar controles o países cambia la pregunta; correlación no implica causalidad.'],
 '08a_sem_ml':['SEM por máxima verosimilitud','Estima asociaciones condicionadas entre componentes observados. El modelo completo mantiene la ruta directa; el restringido es un comparador anidado.'],
 '08b_sem_bca':['SEM con intervalos BCa','Corrige sesgo y asimetría bootstrap bajo el procedimiento archivado. El bootstrap de primera imputación no integra toda la incertidumbre de faltantes.'],
 '08c_sem_probit':['SEM ordinal probit','Adapta el modelo a indicadores ordinales. Sus coeficientes no comparten la escala de un modelo lineal.'],
 '08d_sem_fiml':['Estimación archivada como FIML','Este alias requiere cautela: la revisión identifica el objetivo MLW y no certifica un FIML auténtico. Consultar la receta y la procedencia.'],
 '08e_sem_residuos':['Residuos del SEM','Compara lo observado con lo predicho. Un residuo nacional no demuestra liderazgo, acción comunitaria ni una explicación causal.'],
 '08f_sem_diagrama':['Diagrama del modelo','Representa las rutas estimadas; la dirección de una flecha es una decisión de especificación, no evidencia temporal.'],
 '09_pls_sem':['PLS-SEM','Construye componentes y estima relaciones bajo otro procedimiento. No constituye un voto independiente a favor de una hipótesis.'],
 '10a_bayesiano':['Modelo bayesiano','Describe distribuciones posteriores condicionadas al modelo y sus priors. El modelo sobre promedios de imputaciones no equivale a inferencia conjunta de todos los faltantes.'],
 '10b_bayesiano_comparacion':['Comparación de priors','Muestra cuánto cambian los resultados con los supuestos previos; los priors derivados de los mismos datos son sensibilidad circular.'],
 '10c_bayes_priors_externos':['Priors de otras regiones','Utiliza información de regiones distintas bajo una receta documentada. La transferencia depende de comparabilidad y contexto.'],
 '11a_process':['Regresiones de rutas · PROCESS','Descompone asociaciones mediante regresiones. Su coincidencia algebraica con otros procedimientos no añade una replicación independiente.'],
 '11b_ridge':['Regresión regularizada · Ridge','Reduce inestabilidad por colinealidad a cambio de sesgo. La penalización cambia las estimaciones y su interpretación.'],
 '12a_ind_bootstrap':['Productos indirectos bootstrap','Propaga variación de los productos de rutas. La suma, diferencia y cociente responden a preguntas distintas; el cociente es inestable si el total se aproxima a cero.'],
 '13_cuantilica':['Regresión cuantílica','Examina asociaciones en partes distintas de la distribución condicional de I13. No describe trayectorias temporales de países.'],
 '14_fsqca':['Configuraciones · fsQCA','Busca combinaciones de condiciones bajo calibraciones explícitas. Necesidad y suficiencia configuracionales no identifican efectos causales.'],
 '14b_fsqca_sensibilidad':['Sensibilidad de fsQCA','Cambia anclas de calibración y comprueba estabilidad de configuraciones. Las conclusiones dependen de esas decisiones.'],
 '15_ggm':['Red de asociaciones parciales','Representa dependencias condicionadas; una arista no tiene orientación causal.'],
 '16_lpa':['Perfiles de países · LPA','Agrupa perfiles semejantes bajo el modelo; los grupos no son categorías naturales ni etapas universales.'],
 '17_lasso':['Selección regularizada · Lasso','Explora predictores bajo penalización. La selección no identifica importancia causal y puede variar entre muestras.'],
 '18a_evalues':['E-values','Cuantifica sensibilidad bajo una transformación y supuestos concretos. Revisar la escala antes de interpretar su magnitud.'],
 '18b_rosenbaum':['Sensibilidad de Rosenbaum','Explora sensibilidad a sesgo no observado bajo el diseño implementado; su uso no elimina confusión.'],
 '18c_maxwell_cole':['Sesgo de mediación transversal','Examina la fragilidad de lecturas longitudinales a partir de datos transversales. No reconstruye una secuencia temporal observada.'],
 '18d_cinelli_hazlett':['Confusión no observada','Cuantifica qué fuerza tendría un confusor para alterar la asociación, usando referencias observadas. No prueba que ese confusor exista o no exista.'],
 '19a_mediacion_serial':['Rutas en serie','Especifica productos de rutas encadenadas; el orden se impone y no se aprende de la sección transversal.'],
 '19b_moderaciones':['Interacciones','Examina si una asociación cambia con otra variable. La interacción depende de la escala y del soporte de los datos.'],
 '19c_segmentado':['Modelos segmentados','Permite pendientes distintas por tramos. Un punto de cambio ajustado no establece un umbral de política pública.'],
 '19d_moderaciones_resumen':['Síntesis de interacciones','Reúne resultados de moderación con sus diferencias de especificación.'],
 '20_espacial':['Dependencia geográfica','Moran y vecindad describen patrones espaciales; proximidad no explica el mecanismo ni equivale a independencia estadística.'],
 '21_indicador1':['Promoción y participación · I1','Explora el papel de I1 en las asociaciones especificadas, sin atribuir causalidad a la sociedad civil.'],
 '22_sensibilidad':['Escenarios S1–S6','Cambia indicadores, agregación, población o forma funcional. Cada cambio delimita una dependencia del resultado, no un voto de confirmación.'],
 '22b_multiverso':['Multiverso de especificaciones','Explora pesos, imputación, atípicos, escala de I13 y covariables. Las proporciones de signo son descripciones de decisiones relacionadas, no probabilidades de que una hipótesis sea cierta.'],
 '23_outliers':['Países influyentes y atípicos','Evalúa dependencia de observaciones concretas. Excluir un país cambia la población y necesita justificación sustantiva.'],
 '25_process_tracing':['Selección de casos cualitativos','Propone casos desde patrones y residuos. La evidencia de campo sigue siendo necesaria para explicar los mecanismos.'],
 '26a_dag':['Supuestos y DAG','Expone supuestos causales para discutirlos; dibujar un DAG no identifica automáticamente sus efectos.'],
 '26b_hipotesis':['Hipótesis y estimandos','Reúne los resultados por hipótesis. El conteo de métodos relacionados no equivale a replicaciones independientes.'],
 '26c_validaciones':['Comprobaciones internas','Verifica coherencia de cálculos y contratos. Corrección del software no garantiza causalidad o calibración universal.'],
 '26d_reproducibilidad':['Procedencia y reproducibilidad','Conserva parámetros y referencias del cálculo. Consultar hashes y versión antes de atribuir una ejecución a la receta actual.'],
 '27_comparacion_casuisticas':['Comparación de casuísticas','Reúne rutas, ajuste y correcciones FDR. C1 es primaria retrospectiva; C2–C5 y C7–C9 son familias exploratorias.'],
 '29a_dominancia':['Importancia predictiva','Reparte explicación estadística entre predictores relacionados. No reparte efectos de intervenciones.'],
 '29b_tost':['Equivalencia · TOST','Contrasta equivalencia dentro de márgenes explícitos. No rechazar una diferencia y demostrar equivalencia son decisiones distintas.'],
 '29c_jackknife_paises':['Omisión de países','Retira un país por vez para evaluar influencia. Las omisiones comparten datos y no son muestras independientes.'],
 '29d_factor_unico':['Dimensión común','Compara una representación conjunta con componentes separados. Un ajuste similar puede limitar la atribución por dimensión.'],
 '29e_curvilineo':['No linealidad','Explora formas curvas de asociación, sujetas a tamaño muestral y variación disponible.'],
 '29f_centralidad_ggm':['Centralidad en redes','Resume posición en la red estimada. Centralidad no equivale a capacidad de intervención.'],
 '32_constructo_unico':['Uno frente a tres componentes','Contrasta representaciones, restricciones y predicción; evita confundir un modelo parsimonioso con una dimensión causal única.'],
 '32b_pesos_compuestos':['Sensibilidad a los pesos','Examina agregación aritmética, geométrica y pesos alternativos. Una clasificación puede cambiar sin que cambien los indicadores observados.'],
 '34_validacion_externa_i13':['Validación externa de I13','Compara I13 con Clark 2020 y EIU 2015. Las fechas, coberturas y definiciones diferentes limitan la lectura de concordancia.'],
 '40a_covariables_sociologicas':['Contexto social e institucional','Explora desarrollo, gobernanza, democracia y demografía. Estos análisis no convierten C1 en un modelo ajustado por contexto.'],
 '40b_brecha_urbano_rural':['Brecha urbano-rural','Describe diferencias observadas entre ámbitos cuando hay subítems disponibles; no mide toda la desigualdad territorial.'],
 '41_mapa_region':['Mapa regional','Localiza indicadores nacionales y documenta sus fuentes. Las fronteras son una referencia geográfica, no una clasificación política.']
};
const NAV=[['inicio','⌂','Visión del estudio'],['mapa','◎','Mapa y países'],['comparar','⇄','Comparar regiones'],['asia','◉','Asia-Pacífico'],['europa','◉','Europa'],['modelos','◇','Casuísticas y modelos'],['robustez','≋','Robustez y sensibilidad'],['medicion','▥','Medición y dimensiones'],['complementarios','⊞','Análisis complementarios'],['simulacion','∿','Simulaciones'],['catalogo','▤','Todos los resultados'],['figuras','▧','Galería de figuras'],['metodologia','?','Guía de interpretación'],['documentacion','↳','Documentos y autoría']];
const state={view:'inicio',unit:'mundo',sample:'depurada',metric:'I13',case:'C1',path:'Acceso -> I13',era:'R2',quantity:'total_indirect',interval:'pct95',compareMetric:'Gobernanza',x:'Gobernanza',y:'I13',q:'',group:'',catunit:'',catstate:'',catsample:'',catscope:'',catedition:'',figq:'',figunit:'asia_pacifico',simmetric:'coverage95',simquantity:'total_indirect',simspec:'',robunit:'asia_pacifico',robcase:'C1',roblayer:'indirectos',refregion:'mundo'};
let charts=[],tableCounter=0,renderToken=0;
const unitName=u=>UL[u]||u;
const titleMethod=m=>METHODS[m]?.[0]||m.replace(/^\d+[a-z]?_/,'').replaceAll('_',' ');
const methodNote=m=>METHODS[m]?.[1]||(m.startsWith('simulacion')?'Resultados computacionales bajo los escenarios y parámetros documentados. La simulación solo evalúa los diseños incluidos.':m.match(/24|13b|33|28_/) ? 'Compara poblaciones, ajuste o predicción bajo supuestos específicos. El mundo contiene los países regionales; la coincidencia no es una replicación independiente.':'Consultar el informe y la receta documentada. El catálogo conserva estados y motivos; disponibilidad no implica validación inferencial.');
function go(view,patch={}){Object.assign(state,patch,{view});const p=new URLSearchParams();for(const [k,v] of Object.entries(state))if(k!=='view'&&v!=='')p.set(k,v);location.hash=view+'?'+p.toString()}
function sync(){const [v,q='']=location.hash.slice(1).split('?');if(v&&NAV.some(x=>x[0]===v))state.view=v;for(const [k,vv] of new URLSearchParams(q))if(Object.hasOwn(state,k))state[k]=vv;for(const key of ['unit','robunit'])if(!Object.hasOwn(D.units,state[key]))state[key]='mundo';if(!['depurada','completa'].includes(state.sample))state.sample='depurada';if(!Object.hasOwn(D.cases,state.case))state.case='C1';if(!Object.hasOwn(DIM,state.metric))state.metric='I13';render()}
function options(obj,chosen){return Object.entries(obj).map(([k,v])=>`<option value="${esc(k)}" ${k===chosen?'selected':''}>${esc(v)}</option>`).join('')}
function select(key,label,obj){return `<label>${label}<select data-state="${key}">${options(obj,state[key])}</select></label>`}
function samples(){return select('sample','Muestra',{depurada:'Depurada',completa:'Completa'})}
function units(){return select('unit','Población',D.units)}
function panel(title,body,sub=''){return `<section class="panel"><div class="panel-heading"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div></div>${body}</section>`}
function notice(text,warn=false){return `<div class="notice ${warn?'warning':''}">${text}</div>`}
function source(text){return `<div class="source">Fuente: ${esc(text)}</div>`}
function heading(title,desc,tag=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div>${tag}</div>`}
function tag(text,legacy=false){return `<span class="tag ${legacy?'legacy':''}">${text}</span>`}
function recordsLink(unit,method,scope=''){return `<button class="link-button" data-catalog-unit="${unit}" data-catalog-q="${method}" data-catalog-scope="${scope}">Consultar resultados originales</button>`}
function descriptiveRows(unit=state.unit){return D.countries[unit+'/'+state.sample]||[]}
function observed(row,key){if(key in IND)return Number.isFinite(row[key])?row[key]:null;const parts={Gobernanza:['I3','I4','I5'],Acceso:['I8','I9','I10'],Capacidad_Operativa:['I11','I12','I6','I7']}[key];return parts&&parts.every(k=>Number.isFinite(row[k]))?parts.reduce((a,k)=>a+row[k],0)/parts.length:null}
function mean(vals){vals=vals.filter(Number.isFinite);return vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null}
function observedNote(){return 'Valores observados, sin imputar. Los componentes se muestran solo cuando están presentes todos sus indicadores. Las medias descriptivas del archivo pueden usar imputaciones y diferir de esta vista.'}
function primaryRows(unit,c=state.case,s=state.sample){return D.tables.primary_coefficients.filter(r=>(!unit||r.unit===unit)&&r.specification===c&&r.sample===s)}
function legacyRows(unit=state.unit,c=state.case){return primaryRows(unit,c)}
function chart(id,traces,layout={}){
 const el=$('#'+id);if(!el)return;charts.push(el);
 for(const axis of ['xaxis','yaxis'])if(typeof layout[axis]?.title==='string')layout[axis].title={text:layout[axis].title};
 if(layout.height===undefined)delete layout.height;
 const finalLayout={showlegend:traces.length>1,font:{family:'Segoe UI, Arial, sans-serif',size:12,color:'#294857'},paper_bgcolor:'transparent',plot_bgcolor:'transparent',margin:{l:65,r:25,t:20,b:60},colorway:COLORS,xaxis:{gridcolor:'#e5edf1',zerolinecolor:'#a8bdc8',automargin:true},yaxis:{gridcolor:'#e5edf1',zerolinecolor:'#a8bdc8',automargin:true},legend:{orientation:'h',y:-.25},hoverlabel:{bgcolor:'white'},...layout};
 if(finalLayout.showlegend===false)delete finalLayout.legend;
 return Plotly.newPlot(el,traces,finalLayout,{responsive:true,displaylogo:false,toImageButtonOptions:{format:'svg',filename:'ATLANTES-E4-'+id},modeBarButtonsToRemove:['lasso2d','select2d'],scrollZoom:false});
}
function forest(id,rows,{point='b',lo='ic_lo',hi='ic_hi',name=r=>unitName(r.unit),xTitle='Coeficiente no estandarizado',height}={}){const valid=rows.filter(r=>Number.isFinite(r[point]));if(!valid.length){$('#'+id).innerHTML='<div class="empty">No hay estimaciones para esta selección.</div>';return}const labels=valid.map(name);chart(id,[{type:'scatter',mode:'markers',x:valid.map(r=>r[point]),y:labels,marker:{size:10,color:valid.map(r=>COLORS[Object.keys(D.units).indexOf(r.unit)%COLORS.length]||COLORS[0])},error_x:{type:'data',symmetric:false,array:valid.map(r=>Number.isFinite(r[hi])?r[hi]-r[point]:0),arrayminus:valid.map(r=>Number.isFinite(r[lo])?r[point]-r[lo]:0),thickness:1.6,width:5,color:'#638794'},customdata:valid.map(r=>[r[lo],r[hi],r.n??'']),hovertemplate:'%{y}<br>Estimación: %{x:.4f}<br>Intervalo: [%{customdata[0]:.4f}, %{customdata[1]:.4f}]<br>N: %{customdata[2]}<extra></extra>'}],{margin:{l:180,r:30,t:15,b:60},height,xaxis:{title:xTitle,zeroline:true,zerolinewidth:1.4,zerolinecolor:'#c92d28',gridcolor:'#e3ebef',automargin:true},yaxis:{autorange:'reversed',automargin:true},showlegend:false})}
function map(id,unit,metric='I13',{hero=false,onCountry}={}){const el=$('#'+id);if(!el)return;const rows=descriptiveRows(unit),byIso=new Map(rows.map(r=>[r.iso3,r]));const width=Math.max(el.clientWidth,300),height=hero?290:Math.max(290,Math.min(width*.52,450));const svg=d3.select(el).append('svg').attr('viewBox',`0 0 ${width} ${height}`).attr('role','img').attr('aria-label',`Mapa de ${unitName(unit)}: ${DIM[metric]||metric}`);const projection=d3.geoEqualEarth();if(unit==='mundo'||hero)projection.fitExtent([[8,8],[width-8,height-8]],{type:'Sphere'});else{const focus=GEO.features.filter(f=>byIso.has(f.properties.iso3));projection.fitExtent([[25,20],[width-25,height-25]],{type:'FeatureCollection',features:focus})}const path=d3.geoPath(projection),g=svg.append('g'),scale=d3.scaleLinear().domain([1,2,3,4]).range(['#e0eeea','#93c4b9','#348c91','#163e51']);const ocean=hero?'#163e51':'#f5f9fb';el.style.background=ocean;g.append('path').datum({type:'Sphere'}).attr('d',path).attr('fill',ocean);if(hero)g.append('path').datum(d3.geoGraticule10()).attr('d',path).attr('fill','none').attr('stroke','#b9d2dc').attr('stroke-opacity',.12).attr('stroke-width',.5);
const tip=$('#tooltip');function over(event,row,name){const v=row?observed(row,metric):null;tip.hidden=false;tip.innerHTML=`<strong>${esc(row?.Country||name)}</strong><br>${esc(DIM[metric]||metric)}: ${fmt(v)}<br><span class="muted">${row?'Dato observado · '+row.iso3:'Fuera de la cohorte seleccionada'}</span>`;tip.style.left=Math.min(event.clientX+14,innerWidth-285)+'px';tip.style.top=Math.min(event.clientY+10,innerHeight-110)+'px'}
g.selectAll('path.country').data(GEO.features).join('path').attr('class','country').attr('d',path).attr('fill',f=>{const row=byIso.get(f.properties.iso3);const v=row?observed(row,metric):null;return hero?(row?'#8eb5c2':'#446a7a'):(v===null?(row?'#d5dde3':'#e7edf0'):scale(v))}).attr('opacity',f=>!hero&&!byIso.has(f.properties.iso3)?.55:1).on('mousemove',(e,f)=>over(e,byIso.get(f.properties.iso3),f.properties.nombre)).on('mouseleave',()=>tip.hidden=true).on('click',(e,f)=>{const row=byIso.get(f.properties.iso3);if(row&&onCountry){g.selectAll('.selected').classed('selected',false);d3.select(e.currentTarget).classed('selected',true);onCountry(row)}});
if(!hero){const centers=(D.centroids||[]).filter(c=>byIso.has(c.iso3));g.selectAll('circle').data(centers).join('circle').attr('cx',c=>projection([c.lon,c.lat])[0]).attr('cy',c=>projection([c.lon,c.lat])[1]).attr('r',2.5).attr('fill','#c92d28').attr('stroke','white').attr('stroke-width',.7).attr('opacity',.75).style('cursor','pointer').on('mousemove',(e,c)=>over(e,byIso.get(c.iso3),c.iso3)).on('mouseleave',()=>tip.hidden=true).on('click',(e,c)=>onCountry?.(byIso.get(c.iso3)));const zoom=d3.zoom().scaleExtent([1,9]).filter(e=>e.type!=='wheel'&&(!e.ctrlKey||e.type==='wheel')&&!e.button).on('zoom',e=>g.attr('transform',e.transform));svg.call(zoom);const ctrl=document.createElement('div');ctrl.className='map-tools';ctrl.innerHTML='<button aria-label="Acercar mapa">+</button><button aria-label="Alejar mapa">−</button><button aria-label="Restablecer mapa">↺</button>';el.append(ctrl);const bs=ctrl.querySelectorAll('button');bs[0].onclick=()=>svg.call(zoom.scaleBy,1.5);bs[1].onclick=()=>svg.call(zoom.scaleBy,1/1.5);bs[2].onclick=()=>svg.call(zoom.transform,d3.zoomIdentity)}
}
function countryCard(row,id='country-detail'){const el=$('#'+id);if(!el)return;el.innerHTML=`<div class="country-card"><h3>${esc(row.Country)}</h3><span class="country-code">${esc(row.iso3)} · ${esc(row.WHO_Region||'')}</span><div class="mini-bars">${['Gobernanza','Acceso','Capacidad_Operativa','I13'].map(k=>{const v=observed(row,k);return `<div class="mini-row"><span>${k==='Capacidad_Operativa'?'Capacidad':k==='I13'?'Servicios (I13)':k}</span><div class="mini-track"><div class="mini-fill" style="width:${v===null?0:v/4*100}%"></div></div><strong>${fmt(v,2)}</strong></div>`}).join('')}</div><p class="small muted">Población: ${fmt(row.Population_2023,0)}<br>I8: ${esc(row.I8_fuente||'consultar fuente')}<br>I13: ${esc(row.I13_fuente||'consultar fuente')}</p><p class="small">${Object.keys(IND).filter(k=>row[k]===null).length} de 14 indicadores sin dato observado.</p></div>`}
function legend(){return '<div class="legend"><span>1</span><span class="legend-scale"></span><span>4</span><span>Gris: sin dato / fuera de cohorte</span><span><i class="legend-dot" style="background:#c92d28"></i>Centroides de países</span></div>'}
function download(name,content,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function csvText(rows){const cols=unique(rows.flatMap(r=>Object.keys(r)));const cell=v=>'"'+String(v??'').replaceAll('"','""')+'"';return '\ufeff'+cols.map(cell).join(',')+'\r\n'+rows.map(r=>cols.map(k=>cell(r[k])).join(',')).join('\r\n')}
function table(id,rows,{columns,pageSize=12,filename=id}={}){const el=$('#'+id);if(!el)return;let page=0,sortKey='',asc=true,query='';const keys=columns||unique(rows.flatMap(r=>Object.keys(r)));let selected=rows;const renderTable=()=>{selected=rows.filter(r=>!query||Object.values(r).some(v=>String(v??'').toLowerCase().includes(query)));if(sortKey)selected=[...selected].sort((a,b)=>{const x=a[sortKey],y=b[sortKey];if(x===null||x===undefined)return 1;if(y===null||y===undefined)return -1;return (x!==''&&y!==''&&Number.isFinite(Number(x))&&Number.isFinite(Number(y))?Number(x)-Number(y):String(x).localeCompare(String(y)))*(asc?1:-1)});page=Math.min(page,Math.max(0,Math.ceil(selected.length/pageSize)-1));el.innerHTML=`<div class="table-toolbar"><label>Buscar en tabla <input class="table-search" aria-label="Buscar en tabla" value="${esc(query)}" placeholder="País, variable, valor…"></label><span>${fmt(selected.length,0)} filas</span><button class="download-table">Descargar CSV completo</button></div><div class="table-wrap"><table><thead><tr>${keys.map(k=>`<th scope="col"><button data-sort="${esc(k)}">${esc(k)} ${sortKey===k?(asc?'↑':'↓'):''}</button></th>`).join('')}</tr></thead><tbody>${selected.slice(page*pageSize,(page+1)*pageSize).map(r=>`<tr>${keys.map(k=>`<td>${typeof r[k]==='number'?fmt(r[k],6):esc(typeof r[k]==='object'&&r[k]!==null?JSON.stringify(r[k]):r[k]??'—')}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${keys.length}">No hay filas para esta búsqueda.</td></tr>`}</tbody></table></div><div class="table-toolbar" style="margin-top:10px"><span>Exportación de todas las filas de esta tabla, sin redondear.</span><div class="pager"><button class="prev" ${page===0?'disabled':''}>Anterior</button><span>${page+1} / ${Math.max(1,Math.ceil(selected.length/pageSize))}</span><button class="next" ${(page+1)*pageSize>=selected.length?'disabled':''}>Siguiente</button></div></div>`;$('.table-search',el).oninput=e=>{query=e.target.value.toLowerCase();page=0;const pos=e.target.selectionStart;renderTable();const input=$('.table-search',el);input.focus();input.setSelectionRange(pos,pos)};$$('[data-sort]',el).forEach(b=>b.onclick=()=>{asc=sortKey===b.dataset.sort?!asc:true;sortKey=b.dataset.sort;renderTable()});$('.prev',el).onclick=()=>{page--;renderTable()};$('.next',el).onclick=()=>{page++;renderTable()};$('.download-table',el).onclick=()=>download('ATLANTES-'+filename+'.csv',csvText(rows),'text/csv;charset=utf-8')};renderTable()}
function overview(){return `<section class="hero"><div class="hero-copy"><h1>Un mapa para comprender los cuidados paliativos</h1><p>Gobernanza, acceso a medicamentos, capacidad y servicios: explora las asociaciones, sus alternativas y la incertidumbre de cada resultado.</p><button data-go="mapa">Explorar el mapa</button><p class="credit">Fernando Cagigas &amp; Laura Monzón<br>ATLANTES · Universidad de Navarra</p></div><div class="hero-map"><div class="map" id="hero-map"></div></div></section><div class="stat-strip"><div class="stat"><strong>${D.countries['mundo/completa'].length}</strong><span>Países y territorios en la cohorte mundial</span></div><div class="stat"><strong>14</strong><span>Indicadores del World Map 2025</span></div><div class="stat"><strong>${Object.keys(D.cases).length}</strong><span>Casuísticas activas · C6 retirada</span></div><div class="stat"><strong>${fmt(D.meta.records,0)}</strong><span>Entradas de la ejecución definitiva</span></div></div><div class="grid-2">${panel('El patrón conjunto en cada población','<div id="overview-forest" class="chart tall"></div>'+notice('C1: suma de los productos de las vías de acceso y capacidad. Los intervalos describen incertidumbre asociacional. Incluir cero no demuestra ausencia de relación.')+source('Ejecución '+D.meta.run_id+' · C1 · depurada · percentil 95 %'))}${panel('Ocho preguntas sobre el mismo sistema',`<div class="formula">Gobernanza → Acceso y capacidad → Servicios</div><p>C7 sitúa capacidad antes que acceso. La nueva C9 invierte ese orden. Ambas conservan las rutas directas: la secuencia es una hipótesis de especificación.</p><p>Los datos son nacionales y transversales. Las flechas no establecen precedencia temporal ni efectos de políticas.</p><div class="row-links"><button data-go="modelos">Comparar casuísticas</button><button data-go="robustez">Examinar sensibilidad</button></div>`)}</div>${panel('Cobertura de la colección',`<p>Nueve unidades geográficas × dos muestras × ocho casuísticas. El catálogo incluye los análisis complementarios, las simulaciones, los resultados no aplicables y sus motivos. SEAR tiene N=10: no se sustituye su SEM no estimable por un cero.</p><div id="overview-coverage"></div>`)}<div class="grid-equal">${panel('Asia-Pacífico',`<p>Una cohorte curada de Asia Sudoriental y Pacífico Occidental. La codificación de I8 e I13 condiciona las comparaciones.</p><button data-go="asia">Abrir el dossier</button>`)}${panel('Europa',`<p>Resultados recalculados para todas las casuísticas, ambas muestras y las sensibilidades comunes al resto del estudio.</p><button data-go="europa">Abrir el dossier</button>`)}</div>${panel('Una colección, con todos sus originales',`<p>${fmt(D.meta.files,0)} archivos descargables. Filtra por población, muestra, método, casuística y estado. Cada figura enlaza con su cálculo y cada descarga conserva los bytes originales.</p><div class="row-links"><button data-go="catalogo">Todos los resultados</button><button data-go="figuras">Figuras y mapas</button><button data-go="documentacion">Análisis y procedencia</button></div>`)}`}
function mountOverview(){map('hero-map','mundo','I13',{hero:true});forest('overview-forest',D.tables.application.filter(r=>r.specification==='C1'&&r.sample==='depurada'&&r.quantity==='total_indirect'),{point:'point',lo:'pct95_low',hi:'pct95_high',xTitle:'Suma de productos · escala de cada población'});table('overview-coverage',D.tables.coverage.map(({scenarios,...r})=>r),{columns:['unit','sample','specification','n','SEM','bootstrap','sensitivity','SEM_reason'],pageSize:9})}
function mapPage(){return heading('El estudio, país a país','Cambia de indicador, consulta una región y selecciona un país en el mapa o en el listado.')+`<div class="controls">${units()}${samples()}${select('metric','Indicador o componente',DIM)}</div><div class="grid-wide">${panel('Distribución observada','<div id="country-map" class="map"></div>'+legend()+`<p class="metric-note">${observedNote()}</p>`+source(`resultados/${state.unit}/${state.sample}/00_datos/unidad/tablas/tabla_analitica.csv`))}${panel('Consultar un país',`<label class="small">País <select id="country-select" style="width:100%;margin:8px 0 20px">${descriptiveRows().map(r=>`<option value="${r.iso3}">${esc(r.Country)}</option>`).join('')}</select></label><div id="country-detail"></div>`)}</div>${state.unit.startsWith('asia')?notice('Asia-Pacífico curada usa síntesis propia de I13. La variante I8 global cambia únicamente I8 y mantiene I13 curado: no constituye una armonización completa.',true):''}${panel('Relaciones entre indicadores',`<div class="controls">${select('x','Eje horizontal',DIM)}${select('y','Eje vertical',DIM)}</div><div class="chart" id="country-scatter"></div><p class="metric-note">Cada punto es un país con ambos valores observados. El gráfico no ajusta confusores ni añade imputaciones.</p>`)}${panel('Datos de la población seleccionada','<div id="country-table"></div>')}`}
function mountMap(){const rows=descriptiveRows();const onCountry=row=>{countryCard(row);$('#country-select').value=row.iso3};map('country-map',state.unit,state.metric,{onCountry});if(rows[0])onCountry(rows[0]);$('#country-select').onchange=e=>onCountry(rows.find(r=>r.iso3===e.target.value));const valid=rows.filter(r=>observed(r,state.x)!==null&&observed(r,state.y)!==null);const groups=unique(valid.map(r=>r.WHO_Region));chart('country-scatter',groups.map((g,i)=>{const subset=valid.filter(r=>r.WHO_Region===g);return {type:'scatter',mode:'markers',name:g,x:subset.map(r=>observed(r,state.x)),y:subset.map(r=>observed(r,state.y)),text:subset.map(r=>r.Country),marker:{size:9,color:COLORS[i],opacity:.8,line:{width:.5,color:'white'}},hovertemplate:'%{text}<br>x: %{x:.3f}<br>y: %{y:.3f}<extra>%{fullData.name}</extra>'}}),{xaxis:{title:DIM[state.x],range:[.8,4.2]},yaxis:{title:DIM[state.y],range:[.8,4.2]}});table('country-table',rows,{columns:['Country','iso3',...Object.keys(IND),'I8_fuente','I13_fuente'],filename:state.unit+'-'+state.sample})}
function comparePage(){const c=D.cases[state.case],paths=c.paths.map(p=>p.join(' -> '));if(!paths.includes(state.path))state.path=paths[0];return heading('Comparar regiones','Una misma ejecución y especificación para examinar magnitudes, intervalos y diferencias de contexto.')+`<div class="controls">${samples()}${select('case','Casuística',Object.fromEntries(Object.keys(D.cases).map(c=>[c,c])))}${select('path','Ruta',Object.fromEntries(paths.map(p=>[p,p.replaceAll('_',' ')])))}</div>${panel('Asociaciones del modelo '+state.case,'<div id="comparison-forest" class="chart tall"></div>'+notice('Coeficientes no estandarizados. Los intervalos y sus grados de libertad proceden del procedimiento documentado en cada resultado. Una diferencia visual no equivale a un contraste formal entre regiones.'))}<div class="grid-equal">${panel('Distribuciones observadas',`<div class="controls">${select('compareMetric','Dimensión',DIM)}</div><div id="region-box" class="chart"></div><p class="metric-note">Regiones OMS y mundo, codificación global; valores observados, sin imputación.</p>`)}${panel('Alcance de la comparación',`<p>${caseExplanation(state.case)}</p><p>El mundo contiene los países regionales. Asia-Pacífico curada combina dos regiones y difiere en I8 e I13; su variante I8 global mantiene I13 curado.</p><p>Las muestras pequeñas, la colinealidad y la variación disponible afectan a las estimaciones. La ausencia de un intervalo estimable no es evidencia de ausencia de relación.</p>${recordsLink('comparativa','')}`)}</div>${panel('Todas las cifras de esta ruta','<div id="comparison-table"></div>')}`}
function mountCompare(){const rows=primaryRows().filter(r=>r.path===state.path);forest('comparison-forest',rows,{name:r=>unitName(r.unit)+' · N='+r.n});table('comparison-table',rows,{columns:['unit','sample','specification','n','path','b','se','ic_lo','ic_hi','p','estado_inferencia','df'],filename:'comparacion-'+state.case});chart('region-box',['AFR','AMR','EMR','EUR','SEAR','WPR','mundo'].map((u,i)=>({type:'box',name:unitName(u),y:descriptiveRows(u).map(r=>observed(r,state.compareMetric)).filter(Number.isFinite),boxpoints:false,marker:{color:COLORS[i]}})),{yaxis:{title:DIM[state.compareMetric],range:[.8,4.2]},showlegend:false,margin:{l:50,r:15,t:15,b:100}})}
function regionPage(which){const u=which==='asia'?'asia_pacifico':'EUR',co=D.cohorts[u+'/'+state.sample]?.datos||{},isAsia=which==='asia';if(state.refregion===u)state.refregion='mundo';const paths=D.cases[state.case].paths.map(p=>p.join(' -> '));if(!paths.includes(state.path))state.path=paths[0];return heading(isAsia?'Asia-Pacífico, en detalle':'Europa, en detalle','Resultados, sensibilidad y comparación regional de la ejecución definitiva.',tag('Ejecución '+D.meta.run_id))+`<div class="controls">${samples()}${select('case','Casuística',Object.fromEntries(Object.keys(D.cases).map(c=>[c,c])))}${select('metric','Indicador del mapa',DIM)}</div><div class="stat-strip"><div class="stat"><strong>${co.n_final??'—'}</strong><span>Países · ${state.sample}</span></div><div class="stat"><strong>${co.n_original??'—'}</strong><span>Antes de exclusiones</span></div><div class="stat"><strong>${co.excluidos?.length??0}</strong><span>Excluidos de esta muestra</span></div><div class="stat"><strong>${isAsia?'I13 curado':'I13 global'}</strong><span>Codificación del resultado</span></div></div><div class="grid-wide">${panel('Geografía de la muestra','<div id="region-map" class="map"></div>'+legend())}${panel('Lectura de país','<div id="region-country"></div>')}</div><div class="grid-equal">${panel('Interpretación de la especificación',`<p>${caseExplanation(state.case)}</p><div id="region-reading"></div>${notice(isAsia?'La variante de I8 global permite examinar la sensibilidad al consumo de opioides; conserva la síntesis curada de I13. No es una armonización completa.':'La media europea puede ocultar diferencias entre países. El modelo describe asociaciones nacionales condicionadas; no demuestra qué política explica la oferta asistencial.',true)}`)}${panel('Rutas hacia servicios especializados','<div id="region-paths" class="chart"></div>')}</div>${panel('Productos indirectos e incertidumbre','<div id="asia-intervals" class="chart"></div><p class="metric-note">Mismos puntos; intervalos percentil y BCa del 95 %. Las etiquetas de las rutas cambian con la casuística. En C8 los totales se definen por raíz.</p>')}${panel('Comparación con otras poblaciones',`<div class="controls">${select('refregion','Referencia',Object.fromEntries(Object.entries(D.units).filter(([v])=>v!==u)))}${select('path','Ruta',Object.fromEntries(paths.map(p=>[p,p.replaceAll('_',' ')])))}</div><div id="region-comparison" class="chart short"></div><div id="region-compare-table"></div>`)}${panel('Continuar el análisis',`<p>Contrasta el patrón con C2, los cambios de muestra y las omisiones de países. La estabilidad de la suma de productos no garantiza estabilidad de su reparto entre vías.</p><div class="row-links"><button data-region-catalog="${u}">Todos los resultados</button><button data-region-figures="${u}">Figuras regionales</button><button data-region-robust="${u}">Sensibilidad de la región</button></div><p class="small muted">Exclusiones: ${esc((co.excluidos||[]).join(', ')||'Ninguna')}.</p>`)}`}
function mountRegion(which){const u=which==='asia'?'asia_pacifico':'EUR';map('region-map',u,state.metric,{onCountry:r=>countryCard(r,'region-country')});if(descriptiveRows(u)[0])countryCard(descriptiveRows(u)[0],'region-country');const rows=primaryRows(u),toward=rows.filter(r=>r.path.endsWith(' -> I13'));forest('region-paths',toward,{name:r=>r.path.replaceAll('_',' ')});$('#region-reading').innerHTML=toward.length?'<ul>'+toward.map(r=>`<li>${esc(r.path.replaceAll('_',' '))}: b=${fmt(r.b)}, IC [${fmt(r.ic_lo)}, ${fmt(r.ic_hi)}]. ${Number.isFinite(r.ic_lo)&&Number.isFinite(r.ic_hi)?r.ic_lo>0?'Asociación positiva en este procedimiento.':r.ic_hi<0?'Asociación negativa en este procedimiento.':'El intervalo incluye cero; la dirección no está resuelta.':'Incertidumbre no evaluable.'}</li>`).join('')+'</ul>':notice('Modelo no estimable: consulta su motivo en el catálogo.',true);const compare=[...rows,...primaryRows(state.refregion)].filter(r=>r.path===state.path);forest('region-comparison',compare,{name:r=>unitName(r.unit)+' · N='+r.n});table('region-compare-table',compare,{columns:['unit','specification','n','path','b','ic_lo','ic_hi','p']});intervalPlot('asia-intervals',D.tables.application.filter(r=>r.unit===u&&r.sample===state.sample&&r.specification===state.case&&r.quantity.startsWith('EI')&&!r.quantity.includes('minus')))}
function modelsPage(){const d=D.cases[state.case];return heading('Casuísticas y modelos','Ocho especificaciones activas. Compara las rutas y su incertidumbre; C6 permanece retirada.')+`<div class="controls">${units()}${samples()}</div><div class="case-tabs">${Object.keys(D.cases).map(c=>`<button data-case="${c}" aria-pressed="${state.case===c}">${c}</button>`).join('')}</div><div class="grid-2">${panel(`${state.case} · ${esc(d.nombre)}`,`<div id="model-diagram" class="model-diagram"></div><p>${caseExplanation(state.case)}</p><details><summary>Ecuaciones del modelo completo y restringido</summary><h3>Completo · principal</h3><pre>${esc(d.modelo_completo)}</pre><h3>Restringido · comparador</h3><pre>${esc(d.modelo_restringido)}</pre></details>`)}${panel('Coeficientes del modelo completo','<div id="model-forest" class="chart"></div>')}</div>${notice('C1 es primaria retrospectiva. Las familias exploratorias BH son C2–C5 y C7–C9. El modelo completo es el principal; el restringido es un comparador. El ajuste no selecciona una dirección causal.')}${panel('Productos de las vías indirectas','<div id="model-indirect" class="chart"></div><div id="model-indirect-table"></div>')}${panel('Ajuste y precisión','<div id="model-fit"></div><div id="model-coefficients"></div>'+recordsLink(state.unit,'08a_sem_ml',state.case))}${panel('C7 y C9: invertir el orden',`<p>C7 coloca capacidad antes que acceso; C9 hace lo contrario. Sus modelos completos comparten los predictores de I13. La descomposición de las vías puede cambiar aun cuando la ecuación final y la asociación total coincidan. Los productos seriales corresponden a rutas diferentes.</p><div id="serial-comparison"></div>`)}${panel('Las ocho preguntas',`<div class="method-grid">${Object.keys(D.cases).map(c=>`<article class="method-card"><h3>${c} · ${esc(D.cases[c].nombre)}</h3><p>${caseExplanation(c)}</p></article>`).join('')}</div>`)}`}
function caseExplanation(c){return {C1:'Gobernanza como raíz; acceso y capacidad como vías paralelas, con asociación directa a I13.',C2:'Separa educación e investigación. EI1 pasa por acceso, EI2 por educación y EI3 por investigación.',C3:'Fusiona gobernanza y capacidad en GobCap. Cambia el predictor y el significado del producto indirecto.',C4:'Acceso como raíz; gobernanza y capacidad como intermediarios. Sus productos responden a otra pregunta que los de C1.',C5:'Capacidad como raíz; acceso y gobernanza como intermediarios. Cambia el estimando respecto a C1.',C7:'Gobernanza → Capacidad → Acceso → Servicios, con rutas directas adicionales. EI1 es serial; EI2 pasa por capacidad y EI3 por acceso.',C8:'Gobernanza y capacidad son raíces correlacionadas; acceso es intermediario común. EI1 parte de gobernanza y EI2 de capacidad; no se suman como si procedieran de una sola raíz.',C9:'Gobernanza → Acceso → Capacidad → Servicios: inversión de C7 con las rutas directas conservadas. EI1 es serial, EI2 pasa por acceso y EI3 por capacidad. Los datos no identifican la secuencia temporal.'}[c]||''}
function mountModels(){const c=D.cases[state.case],d=D.sem[state.unit+'/'+state.sample+'/'+state.case];if(d?.estado!=='ok')$('#model-forest').innerHTML=notice(esc(d?.motivo||'No estimable.'),true);else forest('model-forest',primaryRows(state.unit),{name:r=>r.path.replaceAll('_',' ')});table('model-coefficients',primaryRows(state.unit),{columns:['path','b','se','p','ic_lo','ic_hi','fmi','df','estado_inferencia'],filename:state.unit+'-'+state.case});table('model-fit',['completo','restringido'].filter(k=>d?.[k]?.ajuste).map(k=>({modelo:k,...d[k].ajuste,R2_I13:d[k].r2?.I13?.R2})),{columns:['modelo','N','df','CFI','TLI','RMSEA','SRMR','AIC','BIC','R2_I13']});const rs=D.tables.application.filter(r=>r.unit===state.unit&&r.sample===state.sample&&r.specification===state.case);intervalPlot('model-indirect',rs.filter(r=>Object.hasOwn(c.efectos_indirectos,r.quantity)));table('model-indirect-table',rs,{columns:['quantity','label','point','pct95_low','pct95_high','bca95_low','bca95_high','state','B']});table('serial-comparison',D.tables.application.filter(r=>r.unit===state.unit&&r.sample===state.sample&&['C7','C9'].includes(r.specification)&&['EI1','EI2','EI3','total_indirect','total_effect'].includes(r.quantity)),{columns:['specification','quantity','label','point','pct95_low','pct95_high'],pageSize:10});modelDiagram(c)}
function modelDiagram(c){const el=$('#model-diagram'),serial=['C7','C9'].includes(c.id),w=Math.max(el.clientWidth,400),h=serial?260:300,svg=d3.select(el).append('svg').attr('viewBox',`0 0 ${w} ${h}`).attr('role','img').attr('aria-label','Rutas de '+c.id);const marker=svg.append('defs').append('marker').attr('id','arrow').attr('viewBox','0 -5 10 10').attr('refX',9).attr('refY',0).attr('markerWidth',6).attr('markerHeight',6).attr('orient','auto');marker.append('path').attr('d','M0,-5L10,0L0,5').attr('fill','#6c919f');const nodes=unique(c.paths.flat()),pos=new Map();if(serial){const order=c.efectos_indirectos.EI1;order.forEach((n,i)=>pos.set(n,[55+i*(w-110)/3,155]));}else{const roots=c.raices||[c.raiz],mediators=nodes.filter(n=>!roots.includes(n)&&n!=='I13');roots.forEach((n,i)=>pos.set(n,[65,roots.length===1?150:80+i*140]));mediators.forEach((n,i)=>pos.set(n,[w*.52,mediators.length===1?150:55+i*90]));pos.set('I13',[w-55,150]);}for(const [a,b] of c.paths){const [x,y]=pos.get(a),[xx,yy]=pos.get(b),dx=xx-x,dy=yy-y,L=Math.hypot(dx,dy),sx=x+Math.min(45,L*.2)*dx/L,sy=y+24*dy/L,tx=xx-Math.min(49,L*.22)*dx/L,ty=yy-27*dy/L;const far=serial&&Math.abs(dx)>(w-110)/3*1.2;svg.append('path').attr('d',far?`M${sx},${sy} Q${(x+xx)/2},${150-Math.abs(dx)*.38} ${tx},${ty}`:`M${sx},${sy} L${tx},${ty}`).attr('fill','none').attr('stroke',far?'#a5b7bf':'#397b87').attr('stroke-width',far?1.4:2).attr('marker-end','url(#arrow)');}if(c.id==='C8'){const a=pos.get('Gobernanza'),b=pos.get('Capacidad_Operativa');svg.append('path').attr('d',`M${a[0]-38},${a[1]+23} Q5,150 ${b[0]-38},${b[1]-23}`).attr('fill','none').attr('stroke','#94743b').attr('stroke-dasharray','5 3');svg.append('text').attr('x',5).attr('y',150).attr('font-size',10).text('↔');}for(const [n,[x,y]] of pos){svg.append('rect').attr('x',x-47).attr('y',y-23).attr('width',94).attr('height',46).attr('rx',7).attr('fill',n==='I13'?'#163e51':'#e6f1f3').attr('stroke','#aac6d2');svg.append('text').attr('x',x).attr('y',y+4).attr('text-anchor','middle').attr('fill',n==='I13'?'white':'#163e51').attr('font-size',11).text(n.replace('Capacidad_Operativa','Capacidad').replace('Capacidad_Educacion','Educación').replace('Capacidad_Investigacion','Investigación').replace('I13','Servicios'));}}

Q.indirect_to_total_ratio='Cociente indirecto / total';
const SCENARIOS={bootstrap_seed1:'Bootstrap · corriente 1',bootstrap_seed2:'Bootstrap · corriente 2',MI_seed43:'MI · semilla raíz 43',I8_global:'Codificación global de I8',complete_cases:'Casos completos',full_cohort:'Cohorte completa','delta_+0.5':'Faltantes · desplazamiento +0,5','delta_-0.5':'Faltantes · desplazamiento −0,5',independent_seed43_m20:'Imputación · semilla 43, m=20',m10_nested:'Imputación · m=10 anidadas',m40_nested:'Imputación · m=40 anidadas',spec_C2:'C2 · capacidad subdividida',spec_C4:'C4 · acceso como raíz',spec_C5:'C5 · capacidad como raíz'};
function robustnessPage(){if(!D.cases[state.robcase])state.robcase='C1';const q=quantityLabels(state.robcase);if(!q[state.quantity])state.quantity='total_indirect';return heading('Cuánto dependen los resultados de las decisiones','Mismos escenarios de sensibilidad para todas las regiones y casuísticas estimables.')+`<div class="controls">${select('robunit','Población',D.units)}${samples()}${select('robcase','Casuística',Object.fromEntries(Object.keys(D.cases).map(c=>[c,c])))}${select('quantity','Cantidad',q)}${select('interval','Intervalo 95 %',{pct95:'Percentil',bca95:'BCa'})}</div>${panel('Imputación, semillas, casos completos y delta','<div id="sensitivity-forest" class="chart tall"></div>'+notice(caseExplanation(state.robcase))+'<p class="metric-note">Principal: 20 imputaciones y 10.000 intentos bootstrap. Semillas alternativas: 4.999. Sensibilidad MI y casos completos: 1.999. Delta desplaza solo casillas originalmente ausentes; sus puntos no tienen intervalos.</p><div id="sensitivity-status"></div>')}${panel('Cifras completas de la selección','<div id="sensitivity-table"></div>')}${panel('Dependencia de países concretos','<div id="influence-chart" class="chart"></div><p class="metric-note">Omisión de un país por vez con las imputaciones fijas, sin reimputación ni intervalos. Se muestran las 20 mayores variaciones absolutas; la tabla conserva todas.</p><div id="influence-table"></div>')}${panel('Muestra y codificación','<div id="cohort-sensitivity"></div><p class="metric-note">La muestra completa cambia los países incluidos. En Asia-Pacífico, I8 global modifica solo ese indicador; mantiene I13 curado. Los totales no son directamente intercambiables cuando cambia la raíz.</p>')}${panel('Más preguntas de robustez',`<div class="method-grid">${['22_sensibilidad','22b_multiverso','18d_cinelli_hazlett','23_outliers','32b_pesos_compuestos','18c_maxwell_cole','34_validacion_externa_i13'].map(m=>methodCard(m,state.robunit)).join('')}</div>${recordsLink(state.robunit,'22c_sensibilidad_integral',state.robcase)}`)}`}
function mountRobustness(){const match=r=>r.unit===state.robunit&&r.sample===state.sample&&r.specification===state.robcase&&r.quantity===state.quantity,rs=D.tables.sensitivity_quantities.filter(match),base=D.tables.application.filter(match).map(r=>({...r,scenario:'Principal · B=10000'})),all=[...base,...rs];forest('sensitivity-forest',all,{point:'point',lo:state.interval+'_low',hi:state.interval+'_high',name:r=>SCENARIOS[r.scenario]||r.scenario,xTitle:quantityLabels(state.robcase)[state.quantity]});table('sensitivity-table',all,{columns:['scenario','quantity','n','m','B','point','pct95_low','pct95_high','bca95_low','bca95_high','valid_joint','bootstrap_failures','state','point_only']});const cov=D.tables.coverage.find(r=>r.unit===state.robunit&&r.sample===state.sample&&r.specification===state.robcase);$('#sensitivity-status').innerHTML=notice(cov?cov.sensitivity==='no_aplicable'?'No aplicable: '+esc(cov.SEM_reason):'Estados de escenarios: '+esc(Object.entries(cov.scenarios).map(([k,v])=>(SCENARIOS[k]||k)+': '+v).join(' · ')):'Sin resultados para esta combinación.',cov?.sensitivity!=='ok');const inf=D.tables.country_influence.filter(match).sort((a,b)=>Math.abs(b.change)-Math.abs(a.change));if(inf.length){chart('influence-chart',[{type:'bar',x:inf.slice(0,20).map(r=>r.iso3),y:inf.slice(0,20).map(r=>r.change),marker:{color:inf.slice(0,20).map(r=>r.change>=0?'#167c80':'#bc4b3c')}}],{yaxis:{title:'Cambio respecto al punto principal'},xaxis:{title:'País omitido'}});}else $('#influence-chart').innerHTML=notice('Sin diagnóstico puntual para esta cantidad. Consulta el original para los fallos o las cantidades por otra raíz.');table('influence-table',inf);const us=state.robunit.startsWith('asia_pacifico')?['asia_pacifico','asia_pacifico_i8global']:[state.robunit];table('cohort-sensitivity',D.tables.application.filter(r=>us.includes(r.unit)&&r.specification===state.robcase&&r.quantity===state.quantity),{columns:['unit','sample','n','point','pct95_low','pct95_high','bca95_low','bca95_high']})}
function methodCard(m,u=state.unit){return `<article class="method-card"><h3>${esc(titleMethod(m))}</h3><p>${esc(methodNote(m))}</p>${recordsLink(u,m)}</article>`}
function measurementPage(){return heading('Qué mide cada dimensión','Los componentes del estudio resumen indicadores nacionales de desarrollo de cuidados paliativos. I13 se mantiene fuera de los predictores de C1.')+`<div class="method-grid"><article class="method-card"><h3>Gobernanza</h3><p>Plan nacional, integración en atención primaria y autoridad nacional. Describe una estructura formal de políticas; no mide por sí sola implementación efectiva.</p><code>G = media(I3, I4, I5)</code><p>El pipeline la trata como reflectiva. Esa convención requiere justificación sustantiva.</p></article><article class="method-card"><h3>Acceso a medicamentos</h3><p>Consumo de opioides, disponibilidad de medicamentos y morfina oral. Los indicadores contribuyen a formar la dimensión; pueden no ser intercambiables.</p><code>A = media(I8, I9, I10)</code><p>Componente formativo. AVE y HTMT se leen como diagnósticos auxiliares.</p></article><article class="method-card"><h3>Capacidad operativa</h3><p>Combina educación y especialización con congresos y publicaciones. La actividad investigadora es un indicador indirecto de capacidad, no una medida completa de los profesionales.</p><code>C = media(media(I11, I12), media(I6, I7))</code><p>Componente mixto. C2 separa educación e investigación.</p></article><article class="method-card"><h3>Servicios especializados · I13</h3><p>Resultado de interés: desarrollo nacional de servicios especializados para adultos. No resume calidad, cobertura efectiva, experiencia de pacientes ni toda la integración asistencial.</p><code>Y = I13; I14 describe servicios pediátricos</code><p>I13 curado en Asia-Pacífico y global en las regiones OMS.</p></article></div>${notice('Los indicadores se codifican en una escala de 1 a 4 con posibles valores de síntesis. La escala no convierte una distancia entre niveles en un efecto clínico; cambiar la codificación puede cambiar una asociación.')}<div class="controls">${units()}${samples()}</div>${panel('Disponibilidad de los 14 indicadores','<div id="missingness-chart" class="chart"></div><div id="missingness-table"></div>'+source(`tabla_analitica.csv · ${state.unit}/${state.sample} · datos observados`))}${panel('Diccionario de indicadores','<div id="indicator-table"></div>')}${panel('Evidencia de medición',`<div class="method-grid">${['03_psicometria','04a_ave','04b_htmt','04f_efa','04c_bifactor','04e_omega_h','04g_unifactorial','06_invarianza'].map(m=>methodCard(m)).join('')}</div>`)}`}
function mountMeasurement(){const rs=descriptiveRows();const missing=Object.entries(IND).map(([k,label])=>{const vals=rs.map(r=>r[k]).filter(Number.isFinite);return {indicador:k,definicion:label,N:rs.length,observados:vals.length,faltantes:rs.length-vals.length,porcentaje_faltantes:rs.length?(rs.length-vals.length)/rs.length*100:null,minimo:vals.length?Math.min(...vals):null,maximo:vals.length?Math.max(...vals):null,niveles_observados:unique(vals).length}});chart('missingness-chart',[{type:'bar',x:missing.map(r=>r.indicador),y:missing.map(r=>r.porcentaje_faltantes),marker:{color:'#167c80'},text:missing.map(r=>r.definicion),hovertemplate:'%{x}: %{text}<br>Sin dato: %{y:.1f}%<extra></extra>'}],{yaxis:{title:'Indicadores ausentes (%)',range:[0,Math.max(10,...missing.map(r=>r.porcentaje_faltantes))*1.12]}});table('missingness-table',missing);table('indicator-table',Object.entries(IND).map(([k,v])=>({indicador:k,dimension:['I3','I4','I5'].includes(k)?'Gobernanza':['I8','I9','I10'].includes(k)?'Acceso':['I6','I7','I11','I12'].includes(k)?'Capacidad':k==='I13'?'Resultado':'Contexto / otros servicios',descripcion:v})),{pageSize:14})}
function complementaryPage(){const ms=['07_correlaciones','13_cuantilica','14_fsqca','14b_fsqca_sensibilidad','15_ggm','16_lpa','17_lasso','20_espacial','19a_mediacion_serial','19b_moderaciones','19c_segmentado','29a_dominancia','29b_tost','29c_jackknife_paises','29d_factor_unico','29e_curvilineo','29f_centralidad_ggm','32_constructo_unico','40a_covariables_sociologicas','40b_brecha_urbano_rural','34_validacion_externa_i13','25_process_tracing'];return heading('Otras maneras de interrogar los datos','Configuraciones, perfiles, redes, contexto, predicción y comparación regional. Cada enfoque responde a una pregunta propia.')+`<div class="controls">${units()}${samples()}</div>${notice('El catálogo da acceso a los análisis disponibles, incluidos estados no aplicables. Métodos relacionados no aportan votos independientes; cada procedimiento conserva sus propios supuestos y límites.',true)}<div class="method-grid">${ms.map(m=>methodCard(m)).join('')}</div>${panel('Comparación y transporte regional',`<p>Reestimación regional, Chow, invarianza multigrupo, multinivel, efectos fijos, Simpson y predicción fuera de región están conservados en el archivo. La tarea predictiva y el estimando asociativo son diferentes.</p><div class="row-links">${recordsLink('comparativa','')}</div>`)}`}
function simulationPage(){const rs=D.tables.simulation_metrics,qs=unique(rs.map(r=>r.estimando));if(!qs.includes(state.simquantity))state.simquantity='EI1';if(!['cobertura95','sesgo','rmse','convergencia','tipo_s','tipo_m'].includes(state.simmetric))state.simmetric='cobertura95';return heading('Simulaciones y evaluación computacional','72 celdas del diseño de simulación de C1, con 1.000 repeticiones por celda. Su alcance no se extiende automáticamente a C9 ni a otros modelos.')+`<div class="controls">${select('simquantity','Cantidad',Object.fromEntries(qs.map(q=>[q,q])))}${select('simmetric','Medida',{cobertura95:'Cobertura 95 %',sesgo:'Sesgo',rmse:'RMSE',convergencia:'Convergencia',tipo_s:'Error de signo',tipo_m:'Error de magnitud'})}</div>${panel('Comparación de métodos y tamaños','<div id="simulation-chart" class="chart tall"></div>'+notice('Cada punto es una celda: cambian tamaño, magnitud, correlación, faltantes y heterogeneidad. La cobertura condicionada a resultados válidos debe leerse junto con intentos, fallos y error Monte Carlo.'))}${panel('Todas las métricas y denominadores','<div id="simulation-table"></div>')}${panel('Evaluación conjunta de intervalos',`<div class="controls">${select('simspec','Cantidad conjunta',Object.fromEntries(unique(D.tables.joint_metrics.map(r=>r.quantity)).map(q=>[q,q])))}</div><div id="joint-simulation-chart" class="chart tall"></div><p class="metric-note">Siete escenarios × 400 repeticiones. Intervalos percentil, BCa y Rubin según la cantidad. La tabla conserva cobertura sobre todos los intentos y condicionada a intervalos válidos.</p><div id="joint-simulation-table"></div>`)}${panel('Interpretar la evaluación',`<p>El sesgo compara el promedio con el valor de referencia generado. RMSE reúne desviación y variabilidad. Los errores de signo y magnitud se condicionan a la regla declarada en el protocolo. La simulación de C1 tiene su propia calibración y método de referencia.</p><p>El diseño examina ausencia de faltantes, MCAR y MNAR, colinealidad y heterogeneidad regional. No acredita la cobertura universal de los intervalos empíricos ni identifica causalidad.</p>${recordsLink('simulacion','')}`)}`}
function mountSimulation(){mountJointSimulation();const rs=D.tables.simulation_metrics.filter(r=>r.estimando===state.simquantity);chart('simulation-chart',unique(rs.map(r=>r.estimador)).map((m,i)=>{const a=rs.filter(r=>r.estimador===m);return {type:'scatter',mode:'markers',name:m,x:a.map(r=>r.n),y:a.map(r=>r[state.simmetric]),text:a.map(r=>r.clave),marker:{size:7,color:COLORS[i],opacity:.65},hovertemplate:'%{text}<br>N=%{x}<br>Valor=%{y:.4f}<extra>%{fullData.name}</extra>'}}),{xaxis:{title:'Tamaño simulado'},yaxis:{title:state.simmetric},...(state.simmetric==='cobertura95'?{shapes:[{type:'line',xref:'paper',x0:0,x1:1,y0:.95,y1:.95,line:{color:'#bc4b3c',dash:'dash'}}]}:{})});table('simulation-table',rs,{columns:['k','n','magnitud','faltantes','heterogeneidad','estimador','estimando','R','R_validas','theta','media','sesgo','rmse','cobertura95','cobertura95_mcse','convergencia','tipo_s','tipo_m'],pageSize:15})}

function catalogPage(){const groups=Object.fromEntries(unique(CAT.map(r=>r.group)).sort().map(x=>[x,x]));return heading('Todos los resultados','Un índice exhaustivo de las salidas del estudio, con informes, tablas, figuras y archivos de procedencia. Los estados pertenecen a los archivos originales.')+`<div class="panel"><div class="controls"><label class="grow">Buscar método, archivo o ruta<input id="catalog-search" value="${esc(state.q)}" placeholder="Ej.: multiverso, 08a_sem_ml, fsqca…"></label>${select('catunit','Población',{'':'Todas',...UL})}${select('catsample','Muestra',{'':'Todas',depurada:'Depurada',completa:'Completa',casos_completos:'Casos completos',todas:'No específica'})}${select('group','Familia',{'':'Todas',...groups})}${select('catscope','Casuística / ámbito',{'':'Todos',C1:'C1',C2:'C2',C3:'C3',C4:'C4',C5:'C5',C7:'C7',C8:'C8',C9:'C9',GAC:'Familia GAC',EDINV:'Familia EDINV',GOBCAP:'Familia GOBCAP',unidad:'Unidad'})}${select('catstate','Estado',{'':'Todos',ok:'OK',no_aplicable:'No aplicable',no_convergio:'No convergió',documento:'Documento'})}${select('catedition','Edición',{'':'Todas',...Object.fromEntries(unique(CAT.map(r=>r.edition)).map(x=>[x,x]))})}<button id="reset-catalog">Limpiar filtros</button></div><div id="catalog-list"></div></div>${notice('«OK» significa que la tarea produjo una salida, no que todos sus supuestos estén validados. «No aplicable» conserva el motivo y nunca se interpreta como cero. El visor ofrece los bytes originales; los estados de cada cálculo se muestran junto a sus motivos.')}<div class="row-links"><a href="data/manifest.json" download>Descargar manifiesto de archivos y SHA-256</a><button id="export-catalog">Descargar índice CSV</button></div>`}
function filterCatalog(){const words=state.q.toLowerCase().split(/\s+/).filter(Boolean);return CAT.filter(r=>(!state.catunit||r.unit===state.catunit)&&(!state.catsample||r.sample===state.catsample)&&(!state.group||r.group===state.group)&&(!state.catscope||r.scope===state.catscope)&&(!state.catstate||r.state===state.catstate)&&(!state.catedition||r.edition===state.catedition)&&words.every(w=>(r.source+' '+(r.filenames||[]).join(' ')+' '+titleMethod(r.method)+' '+r.group+' '+r.reason).toLowerCase().includes(w)))}
function catalogItem(r){return `<article class="catalog-item"><div>${tag(r.edition,r.edition==='Histórico')} <span class="tag ${r.state==='no_aplicable'?'alert':'gray'}">${esc(r.state)}</span><h3>${esc(titleMethod(r.method))}</h3><p>${esc(unitName(r.unit))} · ${esc(r.sample)} · ${esc(r.scope)} · ${r.count} archivos</p>${r.reason?`<p>${esc(r.reason)}</p>`:''}<p class="small">${esc(r.source)}</p></div><button data-open="${r.id}">Abrir resultado</button></article>`}
function mountCatalog(){let page=0;const draw=()=>{const rs=filterCatalog(),pages=Math.max(1,Math.ceil(rs.length/18));page=Math.min(page,pages-1);$('#catalog-list').innerHTML=`<div class="table-toolbar"><strong>${fmt(rs.length,0)} entradas · ${fmt(rs.reduce((s,r)=>s+r.count,0),0)} archivos</strong><span>Página ${page+1} de ${pages}</span></div>${rs.slice(page*18,(page+1)*18).map(catalogItem).join('')||'<div class="empty">No hay resultados con estos filtros. Prueba otra población, casuística o nombre de método.</div>'}<div class="pager" style="margin-top:18px"><button id="cat-prev" ${!page?'disabled':''}>Anterior</button><button id="cat-next" ${page+1>=pages?'disabled':''}>Siguiente</button></div>`;$('#cat-prev').onclick=()=>{page--;draw()};$('#cat-next').onclick=()=>{page++;draw();$('#catalog-list').scrollIntoView({block:'start'})}};draw();$('#catalog-search').oninput=e=>{state.q=e.target.value;page=0;draw();updateHashQuiet()};$('#reset-catalog').onclick=()=>go('catalogo',{q:'',catunit:'',catsample:'',group:'',catscope:'',catstate:'',catedition:''});$('#export-catalog').onclick=()=>download('ATLANTES-catalogo.csv',csvText(filterCatalog().map(({figures,...r})=>r)),'text/csv;charset=utf-8')}
function galleryPage(){return heading('Figuras del estudio','Mapas regionales, diagramas, distribuciones, redes y diagnósticos. Cada imagen enlaza con el resultado que la produjo.')+`<div class="controls">${select('figunit','Población',{'':'Todas',...UL})}<label class="grow">Buscar figura<input id="figure-search" value="${esc(state.figq)}" placeholder="Ej.: mapa, multiverso, raincloud, mediacion…"></label>${samples()}</div><div id="gallery-results"></div>`}
function mountGallery(){let page=0;const draw=()=>{const figures=CAT.filter(r=>(!state.figunit||r.unit===state.figunit)&&(r.sample===state.sample||r.sample==='todas')).flatMap(r=>r.figures.map(f=>({...f,record:r}))).filter(f=>(f.name+' '+f.record.method).toLowerCase().includes(state.figq.toLowerCase()));const pages=Math.max(1,Math.ceil(figures.length/18));page=Math.min(page,pages-1);$('#gallery-results').innerHTML=`<div class="table-toolbar"><strong>${fmt(figures.length,0)} figuras</strong><span>Página ${page+1} de ${pages}</span></div><div class="gallery">${figures.slice(page*18,(page+1)*18).map(f=>`<figure class="figure"><a href="${f.url}" target="_blank" rel="noopener"><img loading="lazy" src="${f.url}" alt="${esc(f.name)} · ${esc(unitName(f.record.unit))}"></a><figcaption><strong>${esc(f.name.replace('.png','').replaceAll('_',' '))}</strong><br>${esc(unitName(f.record.unit))} · ${esc(f.record.scope)}<br>${esc(f.record.edition)}</figcaption><button data-open="${f.record.id}">Ver resultado y fuente</button> <a class="small" href="${f.url}" download="${esc(f.name)}">Descargar</a></figure>`).join('')}</div>${!figures.length?'<div class="empty">No hay figuras con estos filtros.</div>':''}<div class="pager" style="margin-top:20px"><button id="fig-prev" ${!page?'disabled':''}>Anterior</button><button id="fig-next" ${page+1>=pages?'disabled':''}>Siguiente</button></div>`;$('#fig-prev').onclick=()=>{page--;draw()};$('#fig-next').onclick=()=>{page++;draw();$('#gallery-results').scrollIntoView({block:'start'})}};draw();$('#figure-search').oninput=e=>{state.figq=e.target.value;page=0;draw();updateHashQuiet()}}
function methodologyPage(){return heading('Leer un resultado sin perder su contexto','Una guía para investigadores: qué se estima, cómo se expresa la incertidumbre y dónde termina la evidencia.')+panel('La pregunta del estudio',`<p class="research-reading">¿Cómo se relacionan gobernanza, acceso a medicamentos y capacidad operativa con el desarrollo nacional de servicios especializados de cuidados paliativos para adultos, y cuánto depende esta descripción de la medición, el contexto y las decisiones analíticas?</p><p>La unidad de análisis es el país o territorio. Las asociaciones ecológicas no se trasladan automáticamente a pacientes o profesionales. Los indicadores son del World Map 2025; la fecha de generación de un resultado no cambia el período de su fuente.</p>`)+`<div class="method-grid"><article class="method-card"><h3>Coeficiente b</h3><p>Cambio asociado en la variable dependiente por unidad del predictor, manteniendo los demás predictores de esa ecuación constantes. Los coeficientes no estandarizados dependen de la escala.</p></article><article class="method-card"><h3>Intervalo y p</h3><p>Un intervalo expresa incertidumbre bajo el procedimiento usado. Incluir cero no demuestra ausencia de asociación. Un p pequeño no mide tamaño, importancia clínica ni probabilidad de que la hipótesis sea verdadera.</p></article><article class="method-card"><h3>Producto indirecto</h3><p>En C1, EI1 multiplica gobernanza → acceso por acceso → I13; EI2 usa capacidad. Son cantidades de la especificación, no efectos causales identificados por este diseño.</p></article><article class="method-card"><h3>Suma, diferencia y cociente</h3><p>EI1 + EI2 resume el patrón conjunto. EI1 − EI2 contrasta las vías en su escala. El cociente indirecto/total puede salir de [0,1] o ser inestable: no es un porcentaje causal mediado.</p></article><article class="method-card"><h3>Imputación múltiple</h3><p>Completa conjuntos de datos bajo supuestos y combina incertidumbre. Las imputaciones no crean nuevos países. Rubin requiere varianza dentro y entre imputaciones; cada receta identifica sus grados de libertad.</p></article><article class="method-card"><h3>Bootstrap percentil y BCa</h3><p>Son procedimientos diferentes para construir intervalos con remuestras. Si discrepan, informa la discrepancia; no selecciones el que excluya cero. Comprueba si el procedimiento incorpora incertidumbre de faltantes.</p></article><article class="method-card"><h3>R², ajuste y predicción</h3><p>R² describe variación explicada dentro de muestra. CFI, RMSEA y otros índices dependen del modelo y sus restricciones. Una predicción fuera de región es otra tarea y puede rendir peor que una referencia simple.</p></article><article class="method-card"><h3>Robustez y multiverso</h3><p>La estabilidad muestra dependencia de decisiones examinadas, sin garantizar ausencia de confusión. Muchas especificaciones comparten datos y ecuaciones; no son replicaciones independientes.</p></article></div>`+panel('Muestras y codificaciones',`<p>La muestra depurada excluye microestados con población observada inferior a 100.000 y países con más de un 30 % de indicadores ausentes. La completa conserva la cohorte original. El mínimo para el SEM es N=15; Asia Sudoriental tiene N=10.</p><p>Asia-Pacífico usa I8 por cuartiles y una síntesis curada de I13. Las regiones OMS usan codificación global. La variante «Asia-Pacífico · I8 global» solo sustituye I8: mantiene la definición curada del resultado.</p>${source('pipeline/core/parametros.py; pipeline/core/casuisticas.py; archivos 00_datos')}`)+panel('Procedencia y vigencia',`<p>Todos los resultados proceden de la ejecución <strong>${esc(D.meta.run_id)}</strong>, con nueve unidades, ambas muestras y las ocho casuísticas activas. C6 sigue retirada. C1 es primaria retrospectiva; C2–C5 y C7–C9 son familias exploratorias.</p><p>La nueva C9 invierte el orden serial de C7. Las rutas directas se conservan. Compartir ecuación final o ajuste no permite elegir una secuencia causal.</p><p>Las sensibilidades abarcan semillas bootstrap, número y semilla de imputaciones, casos completos, desplazamientos delta, muestra e influencia de países. La simulación tiene su propio diseño para C1; no valida automáticamente todas las casuísticas.</p>` )+panel('Preguntas que conviene hacer al abrir una tabla',`<ol class="reading-list"><li>¿Qué población, codificación y países incluye?</li><li>¿Qué ecuación y cantidad estoy leyendo?</li><li>¿De qué versión procede y cómo se calculó el intervalo?</li><li>¿Cambian el signo, la magnitud o la precisión con decisiones razonables?</li><li>¿Qué evidencia adicional permitiría sostener una interpretación sustantiva?</li></ol><button data-go="catalogo">Aplicarlo al archivo de resultados</button>`)}
function docLink(d){return `<a class="document" href="${d.url}" target="_blank" rel="noopener"><strong>${esc(d.name.replaceAll('_',' '))} · ${d.source.split('.').pop().toUpperCase()}</strong><span>${esc(d.edition)} · ${esc(unitName(d.unit))}</span></a>`}
function documentsPage(){return heading('Análisis, fuentes y autoría','Una única colección definitiva, con sus resultados originales y su procedencia.')+`<div class="grid-equal">${panel('Autoría',`<h3>Fernando Cagigas</h3><h3>Laura Monzón</h3><p>Proyecto ATLANTES · Universidad de Navarra</p><p class="muted small">Los datos de contacto, afiliaciones individuales y ORCID se actualizarán más adelante.</p><img src="assets/unav-black-logo.svg" alt="Universidad de Navarra" style="width:240px;max-width:100%;margin-top:18px">`)}${panel('Edición definitiva',`<p>${esc(D.meta.edition)}</p><p>${fmt(D.meta.records,0)} entradas · ${fmt(D.meta.files,0)} archivos · ${fmt(D.meta.figure_count,0)} figuras.</p><p>Generada: ${esc(D.meta.generated.slice(0,10))}. Cada descarga conserva sus bytes originales y SHA-256.</p><a href="data/manifest.json" download>Manifiesto completo de integridad</a>`)}</div>${panel('Análisis de resultados',`<div class="document-list">${D.documents.map(docLink).join('')}</div>${recordsLink('documentacion','')}`)}${panel('Fuentes y reconocimiento',`<p>Datos: <em>2025 World Map</em>, Tripodoro y colaboradores. <a href="https://doi.org/10.1016/j.jpainsymman.2025.07.026">Artículo de la fuente</a>. <a href="https://www.who.int/publications/i/item/9789240033351">Marco de indicadores de la OMS</a>.</p><p>Geografía: Natural Earth 50 m y centroides del proyecto. Logotipos: sitio oficial de la Universidad de Navarra. Gráficos: Plotly.js y D3.js, disponibles localmente.</p><div class="row-links"><a href="THIRD_PARTY_NOTICES.md">Créditos y licencias</a><a href="README.md">Uso y publicación en GitHub Pages</a><button data-go="catalogo">Todos los originales</button></div>`)}`}

function quantityLabels(cid){return {...Object.fromEntries(Object.entries(D.cases[cid].efectos_indirectos).map(([k,r])=>[k,k+' · '+r.join(' → ').replaceAll('Capacidad_Operativa','Capacidad')])),total_indirect:'Suma indirecta · raíz '+D.cases[cid].raiz,total_effect:'Total · raíz '+D.cases[cid].raiz,EI1_minus_EI2:'Contraste EI1 − EI2',indirect_to_total_ratio:'Cociente indirecto / total'}}
function intervalPlot(id,rs){if(!rs.length){$('#'+id).innerHTML=notice('No hay productos estimables para esta selección.',true);return;}chart(id,['pct95','bca95'].map((type,i)=>({type:'scatter',mode:'markers',name:type==='pct95'?'Percentil 95 %':'BCa 95 %',x:rs.map(r=>r.point),y:rs.map((_,j)=>j+(i===0?-.12:.12)),marker:{size:8,symbol:i?'diamond':'circle'},error_x:{type:'data',symmetric:false,array:rs.map(r=>Number.isFinite(r[type+'_high'])?r[type+'_high']-r.point:0),arrayminus:rs.map(r=>Number.isFinite(r[type+'_low'])?r.point-r[type+'_low']:0),width:4},text:rs.map(r=>r.label),hovertemplate:'%{text}<br>%{x:.4f}<extra>%{fullData.name}</extra>'})),{margin:{l:100,r:20,t:20,b:65},yaxis:{tickvals:rs.map((_,i)=>i),ticktext:rs.map(r=>r.quantity),autorange:'reversed'},xaxis:{title:'Producto de coeficientes',zerolinecolor:'#c92d28'}})}


function mountJointSimulation(){const all=D.tables.joint_metrics;if(!all.some(r=>r.quantity===state.simspec))state.simspec='total_indirect';const sel=document.querySelector('[data-state="simspec"]');if(sel)sel.value=state.simspec;const rs=all.filter(r=>r.quantity===state.simspec);chart('joint-simulation-chart',unique(rs.map(r=>r.method)).map(m=>{const a=rs.filter(r=>r.method===m);return {type:'scatter',mode:'markers',name:m,x:a.map(r=>r.coverage_conditional_value),y:a.map(r=>r.cell),customdata:a.map(r=>[r.attempts,r.valid_intervals,r.coverage_all_attempts_value]),hovertemplate:'%{y}<br>Cobertura condicionada: %{x:.3f}<br>Intentos: %{customdata[0]} · válidos: %{customdata[1]}<br>Cobertura sobre intentos: %{customdata[2]:.3f}<extra>%{fullData.name}</extra>',marker:{size:9}}}),{margin:{l:140,r:20,t:15,b:65},xaxis:{title:'Cobertura condicionada a intervalos válidos',range:[0,1.02]},yaxis:{autorange:'reversed'},shapes:[{type:'line',yref:'paper',y0:0,y1:1,x0:.95,x1:.95,line:{color:'#bc4b3c',dash:'dash'}}]});table('joint-simulation-table',rs,{columns:['cell','quantity','method','truth','attempts','valid_intervals','coverage_conditional_value','coverage_conditional_mcse','coverage_all_attempts_value','interval_failure_value','bias','rmse']})}

// Original artifacts are loaded only when requested. The JS wrapper also works under file://.
const recordCache=new Map(),pendingRecords=new Map();
window.ATLAS_RECORD=(id,data)=>{recordCache.set(id,data);pendingRecords.get(id)?.resolve(data);pendingRecords.delete(id)};
function loadRecord(id){if(recordCache.has(id))return Promise.resolve(recordCache.get(id));if(pendingRecords.has(id))return pendingRecords.get(id).promise;let resolve,reject;const promise=new Promise((a,b)=>{resolve=a;reject=b});pendingRecords.set(id,{resolve,reject,promise});const s=document.createElement('script');s.src='data/records/'+id+'.js';s.onerror=()=>{pendingRecords.delete(id);reject(new Error('No se encuentra '+s.src))};document.head.append(s);return promise}
async function fileBytes(f){if(!('DecompressionStream' in window))throw new Error('Se necesita un navegador actualizado compatible con descompresión gzip (Chrome, Edge, Firefox o Safari).');const bytes=Uint8Array.from(atob(f.gzip),c=>c.charCodeAt(0));return new Uint8Array(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer())}
async function fileText(f){return new TextDecoder('utf-8').decode(await fileBytes(f))}
function parseOriginal(text){try{return JSON.parse(text)}catch{let quoted=false,escape=false,out='';for(let i=0;i<text.length;){const c=text[i];if(quoted){out+=c;i++;if(escape)escape=false;else if(c==='\\')escape=true;else if(c==='"')quoted=false;continue}if(c==='"'){quoted=true;out+=c;i++;continue}const m=text.slice(i).match(/^(?:NaN|-?Infinity)(?=\s*[,}\]])/);if(m){out+='null';i+=m[0].length}else{out+=c;i++}}return JSON.parse(out)}}
async function resultObject(payload){const f=payload.files.find(f=>f.name==='resultado.json');return f?parseOriginal(await fileText(f)):null}
function jsonTree(value,name='resultado'){const wrapper=document.createElement('div');wrapper.className='json-tree';const make=(v,k,open=false)=>{if(v===null||typeof v!=='object'){const line=document.createElement('div');line.className='scalar';line.innerHTML=`<strong>${esc(k)}</strong>: ${esc(v===null?'null':v)}`;return line}const details=document.createElement('details'),summary=document.createElement('summary');const entries=Object.entries(v);summary.textContent=k+' · '+(Array.isArray(v)?'lista':'objeto')+' ('+entries.length+')';details.append(summary);let populated=false;const populate=()=>{if(populated)return;populated=true;let offset=0;const more=document.createElement('button');more.textContent='Mostrar siguientes 100 elementos';const add=()=>{for(const [key,val] of entries.slice(offset,offset+100))details.insertBefore(make(val,key),more);offset+=100;more.hidden=offset>=entries.length};details.append(more);more.onclick=add;add()};details.ontoggle=()=>{if(details.open)populate()};details.open=open;if(open)populate();return details};wrapper.append(make(value,name,true));return wrapper}
function csvExplorer(rows,filename){const el=$('#file-body');const columns=rows.columns||unique(rows.flatMap(r=>Object.keys(r)));const numeric=columns.filter(k=>{const present=rows.map(r=>r[k]).filter(v=>v!==''&&v!==null&&v!==undefined);return present.length&&present.filter(v=>Number.isFinite(Number(v))).length===present.length});el.innerHTML='<div id="original-csv-table"></div>'+(numeric.length?'<details id="csv-visualization" style="margin-top:20px"><summary>Crear un gráfico con esta tabla</summary><div class="controls" style="margin-top:15px"><label>Eje X<select id="csv-x">'+options(Object.fromEntries(columns.map(k=>[k,k])),columns.find(k=>!numeric.includes(k))||columns[0])+'</select></label><label>Eje Y<select id="csv-y">'+options(Object.fromEntries(numeric.map(k=>[k,k])),numeric.find(k=>['b','point','beta','estimate','coverage95'].includes(k))||numeric[0])+'</select></label><label>Representación<select id="csv-kind"><option value="scatter">Dispersión</option><option value="bar">Barras</option><option value="line">Líneas en el orden del archivo</option><option value="box">Distribución por X</option></select></label><label>Grupo<select id="csv-group">'+options({'':'Sin agrupar',...Object.fromEntries(columns.filter(k=>!numeric.includes(k)).map(k=>[k,k]))},'')+'</select></label></div><div id="csv-chart" class="chart"></div><p class="metric-note">Gráfico descriptivo de las primeras 3.000 filas; la tabla y la descarga conservan todas. No añade intervalos, ajustes ni inferencia. Las filas mantienen el orden del archivo.</p></details>':'');table('original-csv-table',rows,{filename:filename.replace('.csv',''),pageSize:15});if(!numeric.length)return;const draw=()=>{const x=$('#csv-x').value,y=$('#csv-y').value,kind=$('#csv-kind').value,group=$('#csv-group').value,subset=rows.slice(0,3000).filter(r=>r[y]!==''&&r[y]!==null&&Number.isFinite(Number(r[y]))),groups=group?unique(subset.map(r=>r[group])):['Datos'];chart('csv-chart',groups.map(g=>{const rs=group?subset.filter(r=>r[group]===g):subset;return {type:kind==='line'?'scatter':kind,...(kind==='line'?{mode:'lines+markers'}:kind==='scatter'?{mode:'markers'}:{}),name:String(g),x:rs.map(r=>numeric.includes(x)&&r[x]!==''?Number(r[x]):r[x]),y:rs.map(r=>Number(r[y])),hovertemplate:'%{x}<br>%{y}<extra>%{fullData.name}</extra>'}}),{xaxis:{title:x},yaxis:{title:y},showlegend:groups.length>1&&groups.length<25})};$('#csv-visualization').ontoggle=()=>{if($('#csv-visualization').open)draw()};for(const id of ['csv-x','csv-y','csv-kind','csv-group'])$('#'+id).onchange=draw}
let viewerToken=0;
async function openRecord(id){const rec=CAT.find(r=>r.id===id);if(!rec)return;const token=++viewerToken,dialog=$('#viewer');$('#viewer-title').textContent=titleMethod(rec.method)+' · '+unitName(rec.unit);$('#viewer-source').textContent=rec.source;$('#viewer-content').innerHTML='<p class="loading">Abriendo los originales…</p>';if(!dialog.open)dialog.showModal();try{const payload=await loadRecord(id);if(token!==viewerToken)return;$('#viewer-content').innerHTML=notice(esc(methodNote(rec.method)))+`${tag(rec.edition,rec.edition==='Histórico')} <span class="tag gray">${esc(rec.state)}</span>${rec.reason?notice(esc(rec.reason),true):''}<div class="file-tabs" style="margin-top:18px">${payload.files.map((f,i)=>`<button data-file="${i}" title="${esc(f.source)}">${esc(f.name)}</button>`).join('')}</div><div id="file-preview"></div>`;$$('[data-file]',$('#viewer-content')).forEach(b=>b.onclick=()=>showFile(payload.files[Number(b.dataset.file)],b,token));const initial=payload.files.findIndex(f=>f.name==='informe.txt');const idx=initial>=0?initial:Math.max(0,payload.files.findIndex(f=>f.name==='resultado.json'));await showFile(payload.files[idx],$(`[data-file="${idx}"]`),token)}catch(e){$('#viewer-content').textContent=e.message}}
let fileToken=0;
async function showFile(f,button,ownerToken){const token=++fileToken;$$('[data-file]').forEach(b=>b.classList.toggle('active',b===button));const el=$('#file-preview');el.innerHTML='<p>Cargando '+esc(f.name)+'…</p>';const info=`<div class="source">${esc(f.source)}<br>SHA-256: ${esc(f.sha256)} · ${fmt(f.bytes/1024,1)} KB</div>`;try{if(f.url){el.innerHTML=`<div class="row-links"><a href="${f.url}" target="_blank" rel="noopener">Abrir archivo</a><a href="${f.url}" download="${esc(f.name)}">Descargar original</a></div>${['.png','.svg','.jpg'].includes(f.ext)?`<img src="${f.url}" alt="${esc(f.name)}" style="width:100%;max-height:65vh;object-fit:contain;margin-top:15px">`:f.ext==='.pdf'?`<iframe title="${esc(f.name)}" src="${f.url}" style="width:100%;height:65vh;border:0;margin-top:12px"></iframe>`:'<p>Descarga el documento para abrirlo en tu editor.</p>'}${info}`;return}const bytes=await fileBytes(f);if(token!==fileToken||ownerToken!==viewerToken)return;el.innerHTML='<div class="row-links"><button id="download-original">Descargar original</button><button id="view-raw">Ver texto íntegro</button></div><div id="file-body" style="margin-top:16px"></div>'+info;$('#download-original').onclick=()=>download(f.name,bytes,'application/octet-stream');const text=new TextDecoder().decode(bytes);$('#view-raw').onclick=()=>{$('#file-body').replaceChildren(Object.assign(document.createElement('pre'),{textContent:text}))};if(f.ext==='.json'){$('#file-body').append(jsonTree(parseOriginal(text),f.name));$('#file-body').insertAdjacentHTML('beforeend','<p class="small muted">Los valores no finitos del archivo se visualizan como null. La descarga conserva los bytes originales.</p>')}else if(f.ext==='.csv'){const parsed=d3.csvParse(text);csvExplorer(parsed,f.name)}else if(['.txt','.md','.tex','.bib'].includes(f.ext)){$('#file-body').append(Object.assign(document.createElement('pre'),{textContent:text}))}else{$('#file-body').textContent='Archivo binario o comprimido. Descarga el original para examinarlo.';$('#view-raw').hidden=true}}catch(e){if(token===fileToken)el.innerHTML=notice('No se ha podido mostrar este archivo: '+esc(e.message),true)+info}}

function updateHashQuiet(){const p=new URLSearchParams();for(const [k,v] of Object.entries(state))if(k!=='view'&&v!=='')p.set(k,v);history.replaceState(null,'','#'+state.view+'?'+p.toString())}
function toast(text){const el=$('#toast');el.textContent=text;el.style.display='block';setTimeout(()=>el.style.display='none',3500)}
function render(){renderToken++;const token=renderToken;for(const el of charts){try{Plotly.purge(el)}catch{}}charts=[];$('#tooltip').hidden=true;const nav=NAV.find(n=>n[0]===state.view);$('#breadcrumb').textContent=nav?.[2]||'Atlas';$('#nav').innerHTML=NAV.map(([id,icon,label],i)=>`<a href="#${id}" class="${state.view===id?'active ':''}${i===10?'nav-divider':''}" ${state.view===id?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${label}</a>`).join('');const pages={inicio:overview,mapa:mapPage,comparar:comparePage,asia:()=>regionPage('asia'),europa:()=>regionPage('europa'),modelos:modelsPage,robustez:robustnessPage,medicion:measurementPage,complementarios:complementaryPage,simulacion:simulationPage,catalogo:catalogPage,figuras:galleryPage,metodologia:methodologyPage,documentacion:documentsPage};try{$('#main').innerHTML=(pages[state.view]||overview)();const mounts={inicio:mountOverview,mapa:mountMap,comparar:mountCompare,asia:()=>mountRegion('asia'),europa:()=>mountRegion('europa'),modelos:mountModels,robustez:()=>mountRobustness(token),medicion:mountMeasurement,simulacion:mountSimulation,catalogo:mountCatalog,figuras:mountGallery};mounts[state.view]?.()}catch(e){console.error(e);$('#main').insertAdjacentHTML('afterbegin',notice('No se ha podido cargar parte de esta vista. Abre «Todos los resultados» para consultar los originales. '+esc(e.message),true))}document.title=(nav?.[2]||'Atlas')+' · ATLANTES E4';$('.sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')}
document.addEventListener('change',e=>{const key=e.target.dataset.state;if(key)go(state.view,{[key]:e.target.value})});
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.go)go(b.dataset.go);if(b.dataset.case)go('modelos',{case:b.dataset.case});if(b.dataset.open)openRecord(b.dataset.open);if('catalogUnit' in b.dataset)go('catalogo',{catunit:b.dataset.catalogUnit,q:b.dataset.catalogQ||'',catscope:b.dataset.catalogScope||'',catsample:state.sample,group:'',catstate:'',catedition:''});if(b.dataset.regionCatalog)go('catalogo',{catunit:b.dataset.regionCatalog,q:'',catscope:'',catsample:state.sample,group:'',catstate:'',catedition:''});if(b.dataset.regionFigures)go('figuras',{figunit:b.dataset.regionFigures,figq:''});if(b.dataset.regionRobust)go('robustez',{robunit:b.dataset.regionRobust});});
$('#close-viewer').onclick=()=>{$('#viewer').close();viewerToken++};$('#viewer').addEventListener('click',e=>{if(e.target===$('#viewer')){$('#viewer').close();viewerToken++}});$('#menu').onclick=()=>{const open=$('.sidebar').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open))};$('#share').onclick=async()=>{updateHashQuiet();try{await navigator.clipboard.writeText(location.href);toast('Enlace de la vista copiado')}catch{const input=document.createElement('textarea');input.value=location.href;document.body.append(input);input.select();const copied=document.execCommand('copy');input.remove();toast(copied?'Enlace de la vista copiado':'Copia la dirección de la barra del navegador')}};$('#print').onclick=()=>window.print();window.addEventListener('hashchange',sync);sync();
